def _decode_reference(match: re.Match[str]) -> str:
    """Decode one semicolon-terminated CommonMark character reference."""
    value = match.group(0)
    if value.startswith("&#x") or value.startswith("&#X"):
        codepoint = int(value[3:-1], 16)
        if codepoint == 0 or codepoint > 0x10FFFF or 0xD800 <= codepoint <= 0xDFFF:
            return "\ufffd"
        return chr(codepoint)
    if value.startswith("&#"):
        codepoint = int(value[2:-1], 10)
        if codepoint == 0 or codepoint > 0x10FFFF or 0xD800 <= codepoint <= 0xDFFF:
            return "\ufffd"
        return chr(codepoint)
    return html5.get(value[1:], value)


def _decode_references(text: str) -> str:
    return _ENTITY.sub(_decode_reference, text)


def _restore_references(text: str, references: dict[str, str]) -> str:
    for token, value in references.items():
        text = text.replace(token, value)
    return text


def _matching_bracket(text: str, start: int) -> int | None:
    depth = 0
    escaped = False
    index = start
    while index < len(text):
        char = text[index]
        if escaped:
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == "`":
            run_end = index
            while run_end < len(text) and text[run_end] == "`":
                run_end += 1
            size = run_end - index
            closing = text.find("`" * size, run_end)
            if closing >= 0:
                index = closing + size
                continue
        elif char == "<":
            tag_end = text.find(">", index + 1)
            if tag_end >= 0:
                index = tag_end + 1
                continue
        elif char == "[":
            depth += 1
        elif char == "]":
            depth -= 1
            if depth == 0:
                return index
        index += 1
    return None


def _balanced_destination(text: str, start: int) -> tuple[str, int] | None:
    if start >= len(text):
        return None
    if text[start] == "<":
        end = start + 1
        escaped = False
        while end < len(text):
            if escaped:
                escaped = False
            elif text[end] == "\\":
                escaped = True
            elif text[end] == ">":
                value = text[start + 1:end]
                if "\n" not in value and "\r" not in value and "<" not in value and ">" not in value:
                    return value, end + 1
                return None
            end += 1
        return None
    depth = 0
    end = start
    escaped = False
    while end < len(text):
        char = text[end]
        if escaped:
            escaped = False
        elif char == "\\":
            escaped = True
        elif char in " \t\r\n":
            break
        elif char == "(":
            depth += 1
        elif char == ")":
            if depth == 0:
                break
            depth -= 1
        end += 1
    if end == start or depth:
        return None
    return text[start:end], end


def _title(text: str, start: int) -> tuple[str, int] | None:
    if start >= len(text) or text[start] not in "\"'(":
        return None
    opener = text[start]
    closer = ")" if opener == "(" else opener
    end = start + 1
    escaped = False
    while end < len(text):
        char = text[end]
        if escaped:
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == closer:
            return text[start + 1:end], end + 1
        end += 1
    return None


